fetch('/api/stockdata').then((resp)=>{ return resp.json()}).then((data)=>{
    console.log(data)
      if(data.status===200){
setproductdata(data.apiData)
      }else{
        console.log(data.message)
      }
})
    },[])
    return ( 
        <section>

<div className="container">
<div className="row">


        {productdata.map((result,tt)=>(
            <Producetsrr pdata={result}/>

        ))}
